function PanelHeading({ eyebrow, title, action }: { eyebrow: string; title: string; action?: ReactNode }) { return <div className="panel-heading"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>{action}</div> }
function Metric({ label, value, detail, icon: Icon, tone }: { label: string; value: string; detail: string; icon: LucideIcon; tone: string }) { return <div className={`metric-card ${tone}`}><div className="metric-icon"><Icon size={16} /></div><span className="metric-label">{label}</span><strong>{value}</strong><small>{detail}</small></div> }
function ScheduleItem({ time, course, room, active, duration }: { time: string; course: string; room: string; active?: boolean; duration: string }) { return <div className={`schedule-item ${active ? 'is-active' : ''}`}><span className="schedule-time">{time}</span><span className="schedule-marker" /><div><strong>{course}</strong><small><MapPin size={12} /> {room}</small></div><span className="schedule-duration">{duration}</span>{active && <SignalPill tone="mint">Now next</SignalPill>}</div> }
